import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";

/**
 * Ids of projects in `orgId` that are not `private`, or are `private` but
 * `userId` leads or belongs to. Used to keep a listing's rows and `total` in
 * agreement about which private projects the actor may see — callers that can
 * see every private project (admins, owners, staff) skip this entirely.
 */
export function visibleProjectIdsSubquery(orgId: OrgId, userId: UserId) {
  return getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(
        orgPredicate(projects.orgId, orgId),
        or(
          ne(projects.visibility, "private"),
          eq(projects.leadId, userId),
          inArray(
            projects.id,
            getDb()
              .select({ id: projectMembers.projectId })
              .from(projectMembers)
              .where(
                and(
                  orgPredicate(projectMembers.orgId, orgId),
                  eq(projectMembers.userId, userId),
                ),
              ),
          ),
        ),
      ),
    );
}

