/** Admins, owners and platform staff see every private project without needing membership. */
function canSeeAllPrivateProjects(actor: Actor): boolean {
  return actor.isPlatformStaff === true || hasRoleAtLeast(actor.role, "admin");
}

/**
 * Whether `actor` may see `project` at all. A `private` project is invisible
 * unless the actor is an admin/owner, platform staff, its lead, or an
 * explicit project member; `org` and `public` projects are always visible.
 * Membership and lead checks are read fresh on every call, so a change takes
 * effect immediately.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (canSeeAllPrivateProjects(actor)) return true;
  if (project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/** A private project the actor may not see must behave as if it does not exist. */
async function assertVisible(actor: Actor, project: Project): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", project.id);
  }
