import { afterAll, beforeAll, describe, expect, it } from "vitest";

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("private project visibility (scratch verification)", () => {
  it("hides a private project from non-members but shows it to lead/admin/member", async () => {
    const tenant = await createTenant("privviz", "growth");

    const privateProject = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Secret Ops",
      slug: "secret-ops",
      key: "SEC",
      description: null,
      visibility: "private",
      leadId: tenant.userIds.member,
      color: "#111111",
      targetDate: null,
    });

    // canViewProject direct checks
    expect(await projectService.canViewProject(tenant.actors.viewer, privateProject)).toBe(false);
    expect(await projectService.canViewProject(tenant.actors.member, privateProject)).toBe(true); // lead
    expect(await projectService.canViewProject(tenant.actors.admin, privateProject)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.owner, privateProject)).toBe(true);

    // getProject throws NotFoundError, not PermissionDeniedError, for the viewer
    await expect(
      projectService.getProject(tenant.actors.viewer, tenant.org.id, "secret-ops"),
    ).rejects.toBeInstanceOf(NotFoundError);

    // lead can see it
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, "secret-ops"),
    ).resolves.toMatchObject({ project: { id: privateProject.id } });

    // listProjects excludes it for the viewer, total reflects that
    const asViewer = await projectService.listProjects(tenant.actors.viewer, {
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(asViewer.items.some((p) => p.project.id === privateProject.id)).toBe(false);

    const asAdmin = await projectService.listProjects(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(asAdmin.items.some((p) => p.project.id === privateProject.id)).toBe(true);
    expect(asAdmin.total).toBeGreaterThan(asViewer.total);

    // Adding an explicit project member grants visibility immediately.
    await projectMemberRepo.addProjectMember(tenant.org.id, privateProject.id, tenant.userIds.viewer);
    expect(await projectService.canViewProject(tenant.actors.viewer, privateProject)).toBe(true);
    await projectMemberRepo.removeProjectMember(tenant.org.id, privateProject.id, tenant.userIds.viewer);
    expect(await projectService.canViewProject(tenant.actors.viewer, privateProject)).toBe(false);

    // Writes into the private project 404 for a non-member, not forbidden.
    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, privateProject.id, { title: "Sneaky" }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    // A member of the org (not of the project) creating in the org's normal
    // project still works, sanity check createIssue path is unaffected.
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, privateProject.id, { title: "Legit" }),
    );

    // The org-wide issue list excludes the private project's issues for viewer.
    const issuesAsViewer = await issueService.listIssues(tenant.actors.viewer, {
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(issuesAsViewer.items.some((i) => i.id === issue.id)).toBe(false);

    const issuesAsAdmin = await issueService.listIssues(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(issuesAsAdmin.items.some((i) => i.id === issue.id)).toBe(true);

    // getIssue / getBoard 404 for the viewer.
    await expect(
      issueService.getIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getBoard(tenant.actors.viewer, tenant.org.id, privateProject.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    // Comment thread + posting also 404 for the viewer.
    await expect(
      commentService.getThread(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.createComment(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "hi",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    // But the lead (member) can post and read.
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "hi",
      parentId: null,
      mentionedUserIds: [],
    });
    await expect(
      commentService.getThread(tenant.actors.member, tenant.org.id, issue.id),
    ).resolves.toHaveLength(1);

    // A viewer trying to edit/delete that comment also 404s.
    await expect(
      commentService.updateComment(tenant.actors.viewer, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "edited",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    // org-visibility project is unaffected: viewer can see the seeded project.
    expect(
      await projectService.canViewProject(tenant.actors.viewer, tenant.project),
    ).toBe(true);
  });
});

